K=["kcal","protein","carbs","fat","satFat","fiber","sugar","sodium","potassium","calcium","iron","magnesium","zinc","vitA","vitC","vitD","vitE","vitK","b1","b2","b3","b6","b12","folate"]
import json
rows=[]
for line in RAW.strip().splitlines():
    p=line.split("|"); assert len(p)==7, line
    vals=[float(x) for x in p[6].split()]; assert len(vals)==24,(p[0],len(vals))
    rows.append({"id":p[0],"en":p[1],"he":p[2],"aka":[a for a in p[3].split(",") if a],"serving":p[4],"servingG":float(p[5]),"per100":dict(zip(K,[round(v,3) for v in vals]))})
ids=[r["id"] for r in rows]; assert len(ids)==len(set(ids))
with open(__import__("os").path.join(__import__("os").path.dirname(__file__),"..","app","foods.json"),"w") as f:
    f.write("[\n"+",\n".join(json.dumps(r,ensure_ascii=False,separators=(",",":")) for r in rows)+"\n]\n")
print(len(rows))
